#!/usr/bin/env python3
"""Lições acrescentadas em 01/11/2026, com o motor e as chaves do sítio.

Os textos de ensino e os exercícios são originais. As citações são identificadas
no ponto de uso. Executar este gerador não altera as lições anteriores.
"""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
LESSONS = []

def read(title, text, rot='Lê e confronta'):
    return dict(t='ler', titulo=title, rot=rot, html=text)

def choice(p, options, correct, feedback):
    return dict(t='escolha', p=p, o=options, c=correct, f=feedback)

def vf(p, value, feedback):
    return dict(t='vf', p=p, v=value, f=feedback)

def pairs(p, values, feedback):
    return dict(t='emparelhar', p=p, pares=values, f=feedback)

def order(p, steps, feedback):
    return dict(t='ordenar', p=p, passos=steps, f=feedback)

def fill(p, phrase, options, feedback):
    return dict(t='completar', p=p, frase=phrase,
                lacunas=[dict(o=o, c=c) for o,c in options], f=feedback)

def underline(p, phrase, indices, feedback):
    return dict(t='sublinhar', p=p, frase=phrase, certas=indices, f=feedback)

def lesson(id, title, unit, after, question, cards):
    for i, card in enumerate(cards):
        if card['t'] != 'ler':
            card['g'] = f'{id}-{i}'
    LESSONS.append(dict(id=id, title=title, unit=unit, after=after,
                        question=question, cards=cards))

ADEUS = 'https://ensina.rtp.pt/artigo/adeus-de-eugenio-de-andrade/'
TIGELA = 'https://www.up.pt/casacomum/wp-content/uploads/sites/520/2023/11/pa_versao_final-1.pdf#page=14'
REPORTAGEM = 'https://ensina.rtp.pt/artigo/ana-luisa-amaral-poesia-atenta-ao-mundo/'
GEORGE = 'https://estudoautonomo.dge.mec.pt/sites/default/files/inline-files/27_Portugu%C3%AAs.%C2%BA_ano_O%20conto%20George,%20de%20Maria%20Judite%20de%20Carvalho%20(2).pdf'
AUTO = 'https://run.unl.pt/server/api/core/bitstreams/99f70c8f-bd86-4e14-9ae5-aff8a68c13eb/content#page=78'
MINIATURA = 'https://www.portoeditora.pt/conteudos/recursos/manuais/EXP12_CAE12.pdf#page=22'
FIGURACAO = 'https://estudossaramaguianos.com/wp-content/uploads/2020/03/rev-de-estudos-saramaguianos-2-jc3balia-cristina-figueiredo.pdf#page=9'
DURACAO = 'https://recursos.portoeditora.pt/recurso?id=2363389'

lesson('m9-f16', 'O instante dentro da duração', 2, 'm9-f05',
       'Como pode a gramática fazer sentir uma interrupção?', [
 read('O instante dentro da duração', '<p class="abre">Uma ação prolonga-se. Algo acontece e muda tudo. Como consegue a narração colocar um instante dentro de uma duração?</p><p>Na leitura anterior observaste quem trabalha na construção. Agora vais estudar como as formas verbais e a organização da frase apresentam a continuidade e a rutura.</p>', 'Abre'),
 read('O essencial', '<p>O <strong>tempo verbal</strong> localiza uma situação; o <strong>aspeto</strong> mostra como ela é apresentada: em curso, concluída, repetida, por exemplo. Uma situação longa pode ser apresentada como concluída; uma ação breve pode ser observada enquanto decorre.</p><p>José Saramago usa contrastes temporais na representação do trabalho e do acidente de Francisco Marques, em <i>Memorial do Convento</i>. A gramática participa no efeito narrativo.</p>', 'O essencial'),
 read('Uma ação em curso', '<blockquote>«está a fazer bem o trabalho»</blockquote><p>José Saramago, <i>Memorial do Convento</i>, Editorial Caminho, excerto disponibilizado pela Porto Editora, recurso 2363389, página 1 do PDF. O recurso não identifica o ano nem a página da edição do romance.</p><p><a href="'+DURACAO+'" target="_blank" rel="noopener">Lê o excerto na fonte editorial</a>. A passagem apresenta o trabalho de Francisco Marques e o acidente mortal que o interrompe. A análise seguinte distingue o decorrer de uma ação da apresentação de um acontecimento que a altera.</p>'),
 choice('Que valor tem a construção verbal no recorte citado?', ['Apresenta o trabalho enquanto está em curso.', 'Apresenta o trabalho depois de estar concluído.', 'Apresenta o trabalho como algo ainda prometido.'],0,'Estar a seguido de infinitivo apresenta a ação no seu decorrer. Não informa, por si só, de quanto tempo ela durará nem garante que será concluída.'),
 vf('Uma ação apresentada como concluída tem obrigatoriamente uma duração curta.',False,'A conclusão e a duração são dimensões diferentes. Uma construção que durou anos pode ser apresentada como concluída numa única frase.'),
 pairs('Relaciona cada exemplo didático criado com o modo de apresentar a situação.', [['Estava a transportar a pedra.','Ação observada no seu decorrer'],['Transportou a pedra até ao destino.','Ação apresentada como concluída'],['Transportava uma pedra todos os dias.','Ação apresentada como habitual']], 'As formas verbais trabalham com os restantes elementos da frase. Todos os dias explicita repetição; até ao destino delimita a ação.'),
 read('Mudar o recorte temporal', '<p>Exemplos didáticos criados: A: «A equipa trabalhava quando o apoio cedeu.» B: «A equipa trabalhou durante meses.»</p><p>Em A, a primeira situação fornece um fundo em curso e a segunda introduz uma ocorrência. Em B, uma duração longa é apresentada como um todo. Não confundas imperfeito com lentidão obrigatória nem perfeito com rapidez obrigatória.</p>'),
 fill('Completa a análise do exemplo A.', 'A forma trabalhava apresenta o [1] em curso; cedeu introduz uma ocorrência que [2] essa situação.', [(['trabalho','resultado','intervalo'],0),(['altera','repete','prevê'],0)], 'A relação entre as duas situações produz o efeito de interrupção. Não é uma propriedade isolada de uma palavra fora da frase.'),
 order('Ordena o raciocínio para analisar um contraste aspetual.', ['Identificar as formas verbais','Observar os complementos e os marcadores temporais','Distinguir situação em curso e ocorrência delimitada','Relacionar o contraste com o efeito narrativo'], 'O contexto gramatical vem antes da interpretação. A mesma forma pode participar em valores diferentes conforme os elementos que a acompanham.'),
 underline('No exemplo criado, seleciona o marcador que relaciona a ocorrência com a ação em curso.', 'A equipa trabalhava quando o apoio cedeu.', [3], 'Quando liga as duas situações no tempo. Com os tempos verbais usados, permite apresentar uma ocorrência dentro de um processo em curso.'),
 choice('Que frase criada apresenta uma ação longa como um todo concluído?', ['A equipa trabalhou ali durante três anos.', 'A equipa estava a trabalhar quando chegámos.', 'A equipa trabalhava ali todas as manhãs.'],0,'Trabalhou com durante três anos apresenta uma duração longa como um todo. Concluído não é sinónimo de rápido.'),
 vf('A análise das formas verbais dispensa explicar o efeito da interrupção na narrativa.',False,'Identificar formas é apenas uma etapa. É necessário relacionar o contraste temporal com a mudança que atinge a personagem e a continuidade do trabalho.'),
 read('A gramática não decide tudo', '<p>No excerto, o acidente interrompe a ação de uma pessoa concreta. A continuidade da obra não apaga essa perda. Uma análise que conte apenas verbos deixaria por explicar o efeito humano da mudança.</p><p>Não atribuas culpa ou intenção a uma personagem só porque identificaste uma interrupção. A relação temporal não demonstra, por si só, responsabilidade.</p>'),
 pairs('Distingue três perguntas sobre a cena.', [['Como é apresentada a ação?','Análise do aspeto'],['Que mudança atinge a personagem?','Interpretação do acontecimento'],['Quem é responsável pelo acidente?','Questão que exige provas próprias']], 'As perguntas relacionam-se, mas não são equivalentes. O aspeto ajuda a ler a ocorrência; não fornece sozinho uma conclusão sobre responsabilidade.'),
 choice('Que alteração modifica o aspeto sem exigir um acontecimento diferente?', ['Passar de estava a caminhar para caminhou até à porta.', 'Trocar a pessoa que caminha por outra que permanece sentada.', 'Substituir a caminhada por uma queda que não estava narrada.'],0,'A primeira alteração muda o recorte temporal da caminhada. As outras mudam a ação ou a personagem, e não apenas a sua apresentação.'),
 fill('Completa uma regra de leitura.', 'O valor aspetual depende da forma verbal e do [1]; a interpretação relaciona esse valor com a [2].', [(['contexto','alfabeto','parágrafo'],0),(['narrativa','conjugação','ortografia'],0)], 'Complementos e marcadores ajudam a determinar o valor. A interpretação explica o que esse modo de apresentar o tempo faz sentir ou compreender.'),
 order('Planeia duas versões curtas da mesma cena, sem escrita obrigatória.', ['Escolher uma ação e uma ocorrência que a interrompa','Apresentar primeiro a ação enquanto decorre','Apresentar depois essa ação como um todo','Comparar oralmente os efeitos das duas versões'], 'Conservar a cena permite observar o efeito da alteração gramatical. Se mudasses todos os acontecimentos, seria difícil atribuir a diferença ao aspeto.'),
 choice('Que conclusão liga melhor gramática e interpretação?', ['A rutura temporal torna percetível a interrupção de uma vida.', 'O tempo verbal prova sozinho a responsabilidade pelo acidente.', 'A duração da obra torna irrelevante a perda de quem trabalha.'],0,'A primeira conclusão articula forma e efeito humano. Não transforma a gramática em prova de culpa nem deixa o avanço da obra apagar a pessoa.'),
 vf('No exemplo criado «trabalhava ali todos os dias», o imperfeito apresenta uma situação habitual.',True,'Todos os dias torna explícita a repetição. O imperfeito não serve apenas para apresentar uma ação única interrompida: o valor depende do contexto.'),
 read('Para levar', '<p class="levar">Concluído não significa rápido; em curso não significa eterno.</p><p>Cria oralmente duas versões de uma ação: observada enquanto decorre e apresentada como um todo. Explica a diferença e regressa ao efeito da interrupção no excerto.</p>', 'Para levar'),
])

lesson('m9-f14', 'Um rei em miniatura', 1, 'm9-f01',
       'Que revela um rei quando monta uma basílica sobre a mesa?', [
 read('Um rei em miniatura', '<p class="abre">Um objeto pequeno pode revelar uma ideia enorme de poder. Como passa o narrador de uma miniatura para a caracterização de quem a monta?</p><p>Vais separar o pormenor observado, a interpretação e o limite da comparação.</p>', 'Abre'),
 read('O essencial', '<p>Em <i>Memorial do Convento</i>, José Saramago constrói uma representação ficcional do reinado de D. João V. Um romance histórico não é uma transcrição neutra do passado.</p><p>A <strong>caracterização indireta</strong> faz-se através de ações, objetos e relações. A <strong>sátira</strong> pode expor uma pretensão ao aproximar grandeza e pequenez. O objeto não tem um significado fixo fora do contexto.</p>', 'O essencial'),
 read('O episódio e as fontes', '<p>Resumo didático do capítulo I: D. João V ocupa-se da montagem de uma basílica de São Pedro em miniatura. A cena aproxima a figura régia de uma construção que cabe sobre uma mesa. Lê o episódio na edição da turma, procurando gestos, intervenientes e marcas de escala.</p><p>O <a href="'+MINIATURA+'" target="_blank" rel="noopener">quadro de sequências de <i>Expressões</i>, Porto Editora, p. 22</a> confirma a localização na abertura. A análise de Júlia Cristina Figueiredo, <a href="'+FIGURACAO+'" target="_blank" rel="noopener">«História e ficção na figuração de personagens de <i>Memorial do convento</i>», <i>Revista de Estudos Saramaguianos</i>, n.º 2, julho de 2015, p. 33</a>, fundamenta a relação entre objeto e sátira.</p><p>Este resumo não é uma citação do romance. A leitura integral do capítulo faz-se na edição da turma; as atividades essenciais partem das informações apresentadas aqui.</p>'),
 choice('Que pergunta transforma o objeto num indício de caracterização?', ['Como liga o gesto de montar à figura do rei?', 'Quanto custa comprar uma miniatura semelhante?', 'Que medidas tinha a mesa usada nesta montagem?'],0,'A primeira pergunta relaciona ação e personagem. Preço e medidas só seriam relevantes se o texto lhes atribuísse uma função demonstrável.'),
 vf('Montar uma miniatura é, por si só, prova de incapacidade para governar.',False,'A atividade isolada não prova incapacidade. O efeito satírico depende da apresentação narrativa e do contraste com outras ações, relações e pretensões.'),
 pairs('Liga cada plano à operação de leitura correspondente.', [['Objeto sobre a mesa','Descrever um pormenor material'],['Figura de quem governa','Relacionar gesto e posição'],['Contraste entre escalas','Investigar um efeito satírico']], 'O percurso vai do pormenor à relação. Saltar diretamente para uma etiqueta sobre o rei dispensaria a prova que torna a interpretação discutível e verificável.'),
 read('Comparar sem igualar', '<p>A miniatura e a construção monumental podem ser aproximadas como projetos associados à vontade régia. Mas não têm os mesmos materiais, riscos, custos humanos ou condições de execução.</p><p>Modelo: a escala reduzida permite interrogar a grandeza encenada. O confronto com a obra real obriga depois a perguntar quem trabalha e quem recebe a visibilidade. Esta comparação precisa de conservar as diferenças.</p>'),
 fill('Completa a passagem do pormenor à interpretação.', 'O objeto pode contribuir para a caracterização [1]; a comparação com a obra monumental exige reconhecer [2].', [(['indireta','expressa','absoluta'],0),(['diferenças','identidades','proporções'],0)], 'A caracterização indireta usa ações e relações. Comparar não significa apagar aquilo que distingue as duas construções.'),
 order('Ordena a construção de uma hipótese sobre a cena.', ['Identificar o objeto e a ação','Observar a escala e a posição da personagem','Propor o efeito do contraste','Confirmar a hipótese noutros pormenores do capítulo'], 'A hipótese surge depois da observação e continua sujeita a confirmação. Não basta chamar vaidoso ao rei sem explicar como a narrativa o apresenta.'),
 underline('Seleciona a palavra que limita esta inferência didática criada.', 'O contraste pode diminuir a grandeza encenada.', [2], 'Pode assinala uma hipótese interpretativa. A leitura deve demonstrá-la no contexto em vez de a tratar como uma tradução automática do objeto.'),
 choice('Que comparação preserva uma diferença decisiva?', ['A miniatura tem uma escala distinta do trabalho monumental.', 'A miniatura torna dispensável conhecer o trabalho monumental.', 'A miniatura demonstra um risco idêntico ao trabalho monumental.'],0,'As duas construções podem ser relacionadas, mas a escala e as condições não são equivalentes. A diferença é parte da interpretação, não um obstáculo a ela.'),
 vf('Uma representação satírica de D. João V no romance equivale a um documento que comprova todos os gestos da pessoa histórica.',False,'A personagem tem uma construção literária. Para comprovar acontecimentos históricos são necessárias fontes históricas e critérios próprios, além da leitura do romance.'),
 read('Muda o enquadramento', '<p>Cenas didáticas criadas: A: uma pessoa monta uma miniatura para estudar uma estrutura. B: uma pessoa recebe louvores de todos por encaixar uma peça, enquanto outras trabalham sem reconhecimento.</p><p>O mesmo tipo de objeto participa em relações diferentes. O efeito não depende apenas da miniatura, mas do enquadramento, dos gestos e da distribuição de reconhecimento.</p>'),
 pairs('Relaciona cada cena criada com a pergunta que lhe é mais próxima.', [['Montagem para estudar uma estrutura','Que conhecimento se procura?'],['Louvores por um gesto mínimo','Que grandeza se encena?'],['Trabalho sem reconhecimento','Quem fica fora da visibilidade?']], 'As perguntas nascem das relações apresentadas. Não atribuímos a mesma interpretação a todos os usos de um objeto.'),
 choice('Que alteração tornaria a cena B menos crítica?', ['Reconhecer o contributo de todas as pessoas na construção.', 'Multiplicar os elogios à pessoa que apenas encaixou uma peça.', 'Ocultar ainda mais o trabalho de quem sustenta a construção.'],0,'Reconhecer os contributos altera a desigualdade que sustenta a crítica. As outras mudanças intensificariam o contraste.'),
 fill('Completa uma distinção necessária.', 'A sátira analisa uma representação [1]; a comprovação de um facto histórico exige outra [2].', [(['literária','documental','biográfica'],0),(['fonte','escala','forma'],0)], 'Não se nega a relação do romance com a história. Distinguem-se a interpretação de uma obra e a comprovação documental de um acontecimento.'),
 order('Prepara uma comparação entre o capítulo I e a construção de Mafra.', ['Escolher um pormenor de cada passagem','Identificar quem age e quem recebe reconhecimento','Explicar uma aproximação e uma diferença','Concluir sobre o efeito da representação do poder'], 'O confronto não deve reduzir o trabalho monumental a uma metáfora sem pessoas. Quem executa e quem aparece são perguntas centrais.'),
 choice('Que proposta criativa transfere o procedimento sem copiar o episódio?', ['Representar uma autoridade pelo modo como usa um objeto.', 'Escrever um insulto à autoridade sem construir qualquer cena.', 'Descrever um objeto isolado sem o ligar a ações ou relações.'],0,'A primeira proposta testa a caracterização indireta. O objeto torna-se significativo através de ações e relações observáveis.'),
 vf('Se a mesma miniatura fosse usada noutro contexto, o seu efeito de caracterização poderia mudar.',True,'O sentido de um objeto depende das relações em que aparece. Os exemplos de estudo e de louvor desproporcionado mostram como a mesma atividade pode construir efeitos diferentes.'),
 read('Para levar', '<p class="levar">A escala de um objeto pode pôr em causa a escala de uma pretensão.</p><p>Explica uma hipótese sobre a miniatura e uma diferença que deves preservar quando a comparas com a construção de Mafra. Confirma os pormenores no capítulo I da edição da turma.</p>', 'Para levar'),
])

lesson('m9-f15', 'A festa vista do outro lado', 1, 'm9-f14',
       'Como muda uma cena quando deixamos de olhar apenas para quem assiste?', [
 read('A festa vista do outro lado', '<p class="abre">A mesma praça pode ser um lugar de diversão para uns e de sofrimento para outros. Como torna o narrador essa diferença impossível de ignorar?</p><p>Vais ler o contraste de perspetivas na representação de um auto de fé, sem reproduzir a violência em encenação.</p>', 'Abre'),
 read('O essencial', '<p>No capítulo V de <i>Memorial do Convento</i>, José Saramago põe em tensão a cerimónia pública e a experiência dos condenados. Trata-se de uma representação literária da violência inquisitorial.</p><p>A <strong>ironia</strong> pode surgir quando uma formulação tranquila entra em conflito com aquilo que está a acontecer. O contraste entre pontos de vista obriga a perguntar quem suporta as consequências da cena.</p>', 'O essencial'),
 read('Uma palavra fora de lugar?', '<blockquote>«a descansada leitura das sentenças»</blockquote><p>José Saramago, <i>Memorial do Convento</i>, capítulo V. Recorte citado por Celeste Maria Ferreira Cabo Verde, <i>A Comunicação Oral na Sala de Aula</i>, FCSH, Universidade Nova de Lisboa, setembro de 2011, anexo XI, página 78 do PDF. A apresentação indica p. 49 do romance, sem identificar aí uma edição que permita generalizar essa página.</p><p><a href="'+AUTO+'" target="_blank" rel="noopener">Consulta a fonte académica e a análise do episódio</a>. Lê o capítulo na edição da turma. Nesta cena, a tranquilidade da cerimónia contrasta com o sofrimento de quem é condenado.</p>'),
 choice('Que relação torna crítica a expressão citada?', ['Tranquilidade da leitura perante consequências violentas.', 'Tranquilidade da leitura perante consequências irrelevantes.', 'Tranquilidade da leitura perante consequências imaginadas.'],0,'A palavra que sugere repouso entra em conflito com a gravidade das sentenças. A ironia depende dessa relação, não de a palavra ser sempre irónica.'),
 vf('Identificar a ironia significa concluir que o narrador aprova a violência.',False,'A ironia permite distanciar a narração da aparência solene. O contraste expõe a violência que essa aparência pode normalizar.'),
 pairs('Liga cada plano ao problema de leitura que levanta.', [['Quem observa a cerimónia','Como se transforma sofrimento em espetáculo?'],['Quem recebe a sentença','Que consequências a cerimónia produz?'],['Como a cena é narrada','Que contraste orienta a leitura?']], 'A análise distingue posições e escolhas narrativas. Não atribui a todas as pessoas a mesma experiência apenas por estarem no mesmo lugar.'),
 read('Dois planos em confronto', '<p>A representação aproxima o conforto da assistência e a vulnerabilidade dos condenados. O efeito crítico nasce da coexistência dessas situações, não de uma explicação abstrata sobre o mal.</p><p>Modelo: observa um sinal de tranquilidade, relaciona-o com as consequências da condenação e explica a distância entre as duas experiências. Evita transformar a cena numa curiosidade pitoresca.</p>'),
 fill('Completa uma leitura do contraste.', 'A mesma cerimónia recebe sentidos [1] conforme a posição de quem a vive; o narrador torna essa diferença [2].', [(['distintos','uniformes','imutáveis'],0),(['visível','inócua','secreta'],0)], 'A diferença de posição não é um detalhe exterior. É uma forma de tornar percetível o que a aparência festiva deixa fora do seu centro.'),
 order('Ordena o caminho de uma interpretação da ironia.', ['Localizar uma expressão de tranquilidade','Identificar as consequências da cerimónia','Explicar a tensão entre palavra e situação','Concluir sobre a distância crítica da narração'], 'O efeito resulta de uma relação comprovável. Dizer apenas que há ironia não mostra como ela funciona.'),
 underline('Seleciona a palavra que precisa de ser confrontada com o contexto.', 'a descansada leitura das sentenças', [1], 'Descansada sugere serenidade. O confronto com a violência das consequências transforma essa serenidade num indício crítico.'),
 choice('Que mudança de foco recupera a dimensão humana da cena?', ['Observar o efeito da cerimónia na vida dos condenados.', 'Contar apenas os vários enfeites usados por quem assiste.', 'Avaliar apenas a beleza formal de toda a procissão.'],0,'A mudança de foco não elimina a forma da cerimónia; pergunta quem paga o seu custo e como essa experiência é representada.'),
 vf('Todas as descrições de cerimónias são necessariamente irónicas.',False,'É necessário observar o texto concreto. Sem tensão entre formulação e contexto, a etiqueta ironia pode ser uma interpretação imposta.'),
 read('Testa o mesmo procedimento', '<p>Cena didática criada: numa cerimónia de prémios, a organização elogia o ambiente tranquilo enquanto impede uma trabalhadora de explicar as condições em que fez o trabalho.</p><p>Não é uma equivalência histórica com a Inquisição. Serve apenas para observar um procedimento: pôr em confronto uma aparência pública e uma experiência excluída dessa aparência.</p>'),
 pairs('Distingue os três níveis da comparação proposta.', [['A cerimónia criada para a atividade','Exemplo didático contemporâneo'],['O episódio do capítulo V','Representação literária situada'],['Contrastar aparência e experiência','Procedimento que se pode comparar']], 'Comparar um procedimento não iguala a gravidade nem o contexto dos acontecimentos. Explicitar esse limite torna a analogia mais rigorosa.'),
 choice('Que pergunta melhora a leitura da cena didática?', ['Que voz falta para avaliar a tranquilidade anunciada?', 'Que decoração prova a justiça de tudo o que acontece?', 'Que aplauso dispensa conhecer as condições de trabalho?'],0,'A primeira pergunta procura informação excluída da aparência pública. As outras transformam sinais de aprovação em prova de justiça.'),
 fill('Completa o limite da analogia.', 'Podemos comparar uma [1] narrativa sem declarar os acontecimentos de [2].', [(['estratégia','cronologia','estatística'],0),(['igual gravidade','épocas distintas','natureza diversa'],0)], 'A analogia tem um âmbito: aqui, a construção do contraste. Não apaga diferenças de época, violência, responsabilidade ou consequência.'),
 order('Prepara uma resposta sobre o efeito crítico da cena.', ['Apresentar o contraste de posições','Usar a expressão citada como indício','Explicar a tensão entre tranquilidade e violência','Concluir sem confundir narrador e assistência'], 'A resposta deve atribuir cada posição à instância adequada. O que a assistência aceita não é automaticamente o que a narração aprova.'),
 choice('Que proposta criativa testa o contraste sem encenar a violência?', ['Criar duas legendas para a praça, de posições distintas.', 'Pedir que alguém represente a humilhação de uma pessoa condenada.', 'Repetir as acusações da cena como se fossem factos comprovados.'],0,'As legendas permitem trabalhar foco e seleção de informação. Não exigem reproduzir sofrimento nem validar as acusações representadas.'),
 vf('Retirar o contexto violento pode fazer a expressão citada parecer apenas uma descrição de ritmo.',True,'Sem conhecer as consequências das sentenças, um leitor pode não reconhecer a tensão. O contexto é parte da prova da ironia, não um adorno à análise de palavras.'),
 read('Para levar', '<p class="levar">Uma aparência de festa não diz o que todos vivem.</p><p>Explica como a escolha de uma palavra torna visível o conflito entre duas experiências. Distingue sempre assistência, condenados e narrador.</p>', 'Para levar'),
])

lesson('m8-f16', 'Recorte de George', 2, 'm8-f08',
       'Como se mostra um pensamento sem o pôr numa fala?', [
 read('Recorte de George', '<p class="abre">A descrição começa por um rosto e acaba por uma correção de palavras. Quem está a escolher a maneira de nomear a idade?</p><p>Vais analisar um recorte curto de «George», de Maria Judite de Carvalho, e distinguir aquilo que se vê daquilo que se pensa.</p>', 'Abre'),
 read('O essencial', '<p>Maria Judite de Carvalho é a autora de <i>Seta Despedida</i>, onde se inclui «George» (1995). No conto, a narração cruza perceção e vida interior.</p><p><strong>Narrador</strong> é a instância que conta. <strong>Personagem</strong> participa no mundo narrado. A voz narrativa pode aproximar-se do pensamento de uma personagem sem o apresentar como diálogo. Uma <strong>inferência</strong> precisa de indícios e tem limites.</p>', 'O essencial'),
 read('As palavras confirmadas', '<blockquote class="prosa">«À sua frente uma senhora de idade, primeiro esboçada, finalmente completa, olha-a atentamente. De idade não, George detesta eufemismos, mesmo só pensados, uma mulher velha.»</blockquote><p>Maria Judite de Carvalho, «George», in <i>Seta Despedida</i>, Mem Martins, Europa-América, 1995. Recorte de 25 palavras, tal como se lê na página 1 do documento DGE, #EstudoEmCasa, Português, 12.º ano, Bloco 27. A fonte não indica a página da edição.</p><p><a href="'+GEORGE+'" target="_blank" rel="noopener">Consulta o excerto oficial da DGE</a>. O resto do conto lê-se na edição da turma. As atividades seguintes usam apenas o recorte apresentado.</p>'),
 choice('Que mudança ocorre entre a primeira e a segunda frase?', ['Da perceção da figura para a escolha de palavras.', 'Da apresentação de George para uma fala da autora real.', 'Da recordação de infância para uma notícia histórica.'],0,'A primeira frase apresenta a figura observada. A segunda recusa uma expressão e explicita a atitude de George perante os eufemismos.'),
 vf('O recorte apresenta uma fala pronunciada em voz alta por George.',False,'A referência a palavras apenas pensadas impede tomar a passagem por diálogo pronunciado. O leitor tem acesso a uma avaliação interior.'),
 pairs('Liga cada elemento do recorte ao que permite observar.', [['primeiro / finalmente','Progressão da perceção'],['George detesta eufemismos','Atitude da personagem'],['mesmo só pensados','Plano interior das palavras']], 'Os marcadores temporais organizam a perceção; a referência a George atribui a atitude; a indicação do pensamento impede confundir o recorte com fala audível.'),
 read('Uma correção que caracteriza', '<p>Um eufemismo atenua uma expressão potencialmente dura. No recorte, a designação mais atenuada da idade é recusada e substituída por uma nomeação direta.</p><p>Modelo: observa a recusa, identifica a personagem a quem é atribuída e interpreta a relação com as palavras. Não concluas que já conheces todos os sentimentos de George sobre o envelhecimento.</p>'),
 fill('Completa a análise sem confundir narrador e personagem.', 'A narração permite conhecer uma [1] de George, embora não apresente uma [2] pronunciada.', [(['avaliação','biografia','entrevista'],0),(['fala','rima','cena'],0)], 'O pensamento pode ser representado pela narração. Não precisa de surgir entre marcas de diálogo para caracterizar a personagem.'),
 order('Ordena o percurso da nomeação no recorte.', ['Surge uma designação atenuada da idade','Essa designação é recusada','A atitude perante eufemismos é atribuída a George','Surge uma designação direta da idade'], 'A ordem torna visível a correção lexical. É essa operação, mais do que um retrato físico completo, que abre o acesso à atitude da personagem.'),
 underline('Seleciona, no recorte, a palavra que nega a primeira designação.', 'De idade não, George detesta eufemismos,', [2], 'Não marca a recusa. A vírgula acompanha uma correção que deixa o leitor seguir o movimento do pensamento.'),
 choice('Que conclusão tem apoio suficiente neste recorte?', ['George recusa a expressão atenuada sobre a idade.', 'George conhece toda a história da mulher observada.', 'George diz à mulher aquilo que pensa da sua idade.'],0,'A recusa é explícita e atribuída a George. Conhecer uma história inteira ou falar à mulher são ações que este recorte não comprova.'),
 vf('A figura tornar-se completa na perceção significa que a narração já contou toda a sua vida.',False,'A completude refere-se à apresentação da figura observada. Não equivale a conhecer a sua biografia nem a resolver o sentido do encontro.'),
 read('Experimenta uma mudança', '<p>Exemplos didáticos criados: A: «Ela chamou-lhe velha.» B: «Pensou na palavra velha, mas não a disse.»</p><p>A mudança altera o que acontece entre as personagens e o acesso do leitor à interioridade. Não são versões do conto: servem para testar a diferença entre dizer e pensar.</p>'),
 pairs('Associa cada exemplo criado ao seu efeito narrativo.', [['Ela chamou-lhe velha.','Ato verbal dirigido a alguém'],['Pensou na palavra, mas não a disse.','Acesso a um pensamento não pronunciado'],['O narrador não revela o que ela pensa.','Restrição do acesso à interioridade']], 'A escolha narrativa muda a informação disponível. Uma palavra pensada e uma palavra pronunciada podem ter consequências diferentes na relação.'),
 choice('Que reescrita seria necessária para restringir a cena ao observável?', ['Retirar a informação sobre o pensamento de George.', 'Acrescentar pensamentos de todas as outras pessoas.', 'Apresentar como diálogo tudo o que George pensa.'],0,'Uma descrição limitada ao observável não afirma pensamentos. Transformar pensamento em diálogo muda a ação; não é apenas retirar acesso interior.'),
 fill('Completa o limite da leitura.', 'O recorte caracteriza a relação de George com uma [1]; para interpretar o encontro no conto, é necessária a leitura do [2].', [(['expressão','profissão','paisagem'],0),(['conjunto','prefácio','glossário'],0)], 'O recorte permite uma análise lexical e narrativa precisa. O papel do encontro na estrutura da obra exige ler além dele.'),
 order('Prepara uma resposta breve sobre a caracterização de George.', ['Identificar a correção de palavras','Atribuir a recusa à personagem','Explicar como a narração mostra o pensamento','Limitar a conclusão ao recorte'], 'A resposta liga prova, atribuição e efeito. Evita completar lacunas com acontecimentos ou motivações que não foram apresentados.'),
 choice('Que pergunta permite prosseguir a leitura da edição da turma?', ['Como se liga este encontro aos outros momentos do conto?', 'Que pormenor confirma uma biografia já provada por este recorte?', 'Porque corresponde toda a voz narrativa à opinião da autora?'],0,'A primeira pergunta procura relações no conjunto. As outras pressupõem conclusões que o recorte não autoriza.'),
 vf('Substituir no recorte a correção por uma descrição apenas física retiraria uma pista sobre a atitude de George.',True,'A recusa de uma designação mostra uma relação com a linguagem. Uma descrição apenas física poderia conservar o aspeto da figura e perder essa pista de interioridade.'),
 read('Para levar', '<p class="levar">Uma correção de palavras pode abrir o pensamento de uma personagem.</p><p>Explica oralmente o que muda entre observar, pensar e dizer. Quando leres o conto inteiro, confirma ou revê a tua interpretação deste encontro.</p>', 'Para levar'),
])

lesson('m8-f13', 'Quando as palavras se gastam', 1, 'm8-f04',
       'Como pode um poema mostrar que as palavras deixaram de chegar?', [
 read('Quando as palavras se gastam', '<p class="abre">Uma frase pode continuar correta e já não conseguir aproximar duas pessoas. Que mudou: as palavras ou a relação?</p><p>Na leitura anterior conheceste a abertura de «Adeus». Agora vais testar o contraste entre o passado e o presente e os limites de uma interpretação.</p>', 'Abre'),
 read('O essencial', '<p>Eugénio de Andrade constrói em «Adeus» uma despedida através de imagens concretas. O poema pertence a <i>Os Amantes sem Dinheiro</i> (1950). O sujeito poético é a voz construída pelo poema: não é uma declaração biográfica automática do autor.</p><p>Uma <strong>metáfora</strong> aproxima realidades diferentes. Uma <strong>repetição</strong> pode mostrar insistência ou desgaste. Para interpretar, observa a imagem, compara os momentos e limita a conclusão ao que o texto sustenta.</p>', 'O essencial'),
 read('O recorte e a leitura', '<blockquote>«Já gastámos as palavras pela rua, meu amor,<br>e o que nos ficou não chega»</blockquote><p>Eugénio de Andrade, «Adeus», <i>Os Amantes sem Dinheiro</i>, 1950. Citação de dois versos, conforme a RTP Ensina; a página da edição não é indicada.</p><p><a href="'+ADEUS+'" target="_blank" rel="noopener">Lê o poema completo na RTP Ensina</a>. Observa como o passado de abundância contrasta com o presente da despedida. Podes voltar ao texto em qualquer momento.</p>'),
 choice('Na abertura, que leitura explica melhor o desgaste das palavras?', ['Perderam força dentro desta relação.', 'Desapareceram do vocabulário da língua.', 'Ficaram incorretas segundo a gramática.'], 0, 'O desgaste é uma imagem da perda de eficácia afetiva. A frase continua compreensível; o que deixou de bastar é a linguagem partilhada nesta relação.'),
 vf('O uso de uma forma verbal na primeira pessoa do plural prova que o poema relata a vida do autor.', False, 'A primeira pessoa constrói uma voz. Para afirmar um facto biográfico seria necessária uma fonte independente; a pessoa gramatical não basta.'),
 pairs('Liga a observação ao efeito que permite investigar.', [['Palavras tratadas como algo que se gasta','Metáfora de desgaste'],['Regresso de uma formulação','Insistência pela repetição'],['Passado confrontado com o presente','Contraste temporal']], 'Cada recurso organiza uma relação: material e afetiva, repetida e insistente, passada e presente. Dar o nome ao recurso é o início, não a interpretação completa.'),
 read('Um modelo de interpretação', '<p><strong>Observação:</strong> a abertura aproxima palavras e desgaste. <strong>Relação:</strong> o que era partilhado já não chega para sustentar o vínculo. <strong>Limite:</strong> isso não demonstra que a linguagem seja inútil em todas as relações.</p><p>No poema completo, o silêncio recebe um tratamento diferente e a recordação de uma antiga abundância torna mais forte a perda atual. São contrastes que impedem uma leitura uniforme de tudo como fracasso.</p>'),
 fill('Completa a passagem da identificação para a interpretação.', 'A metáfora não descreve uma perda [1] de palavras: sugere uma perda de [2] na relação.', [(['material','temporal','corporal'],0),(['eficácia','correção','pronúncia'],0)], 'O poema usa uma imagem material para pensar uma mudança afetiva. O efeito está na passagem entre esses dois planos.'),
 order('Ordena os passos de uma interpretação sustentada.', ['Localizar a imagem na abertura','Explicar a relação entre desgaste e vínculo','Confrontar essa leitura com os contrastes do poema','Indicar o que não é possível concluir sobre o autor'], 'A prova antecede a conclusão. O confronto com o conjunto pode afinar a leitura e impede transformar o poema numa biografia.'),
 underline('Neste exemplo didático criado, seleciona as duas palavras que fazem o contraste temporal.', 'Antes aproximava; agora afasta.', [0,2], 'Antes e agora organizam o contraste. A frase é um exemplo criado para observar a estrutura, não um verso de Eugénio de Andrade.'),
 choice('Que efeito tem recordar a antiga abundância no meio de uma despedida?', ['Realça a perda sentida no presente.', 'Anula a rutura anunciada pela voz.', 'Prova a felicidade futura do casal.'],0,'O contraste dá espessura à perda: percebe-se o que existiu e deixou de existir. A recordação não garante um reencontro.'),
 vf('Se o silêncio recebe um tratamento diferente das palavras gastas, a leitura deve reconhecer essa diferença.', True, 'Uma interpretação rigorosa não força todos os elementos a dizer o mesmo. A diferença do silêncio obriga a qualificar a ideia de desgaste.'),
 read('Muda uma decisão', '<p>Exemplos criados para esta lição: A: «Nada do que digo te alcança.» B: «Nunca ninguém consegue dizer nada a ninguém.»</p><p>A primeira formulação situa um limite numa relação. A segunda transforma esse limite numa regra universal. Ao escrever uma apreciação, confirma que não fizeste esta mudança sem prova.</p>'),
 pairs('Classifica as duas formulações criadas e uma decisão de leitura.', [['Nada do que digo te alcança.','Limite situado numa relação'],['Nunca ninguém consegue dizer nada a ninguém.','Generalização sem limite'],['Procuro um contraste antes de concluir.','Procedimento de confirmação']], 'O alcance de uma afirmação importa tanto como o tema. A leitura de um caso não autoriza automaticamente uma regra sobre toda a humanidade.'),
 choice('Que proposta criativa preserva a tensão estudada sem copiar o poema?', ['Um encontro em que a saudação muda de efeito.', 'Uma lista de erros que impede qualquer comunicação.', 'Uma explicação que elimina de vez as ambiguidades.'],0,'Repetir uma saudação em momentos distintos permite experimentar uma mudança de efeito. A criação transfere o contraste, sem imitar versos.'),
 fill('Completa uma conclusão prudente.', 'Neste poema, a linguagem revela uma [1] do vínculo; não estabelece uma lei sobre [2].', [(['mudança','garantia','correção'],0),(['todas as relações','esta relação a dois','duas relações aqui'],0)], 'A expressão neste poema delimita o objeto. A interpretação deve explicar este vínculo e não prometer uma teoria universal do amor.'),
 order('Organiza um pequeno plano de comparação com outro poema já lido.', ['Escolher uma imagem de cada poema','Explicar o efeito de cada imagem no seu contexto','Identificar uma semelhança e uma diferença','Redigir uma conclusão que mantenha essa diferença'], 'Comparar não é encontrar apenas um tema igual. Uma diferença bem sustentada pode ser a descoberta principal.'),
 choice('Que comentário merece revisão por confundir texto e vida?', ['O autor viveu exatamente esta despedida.', 'A voz apresenta uma relação em desgaste.', 'O passado intensifica a perda no presente.'],0,'A primeira frase afirma uma biografia sem prova. As outras descrevem relações observáveis na construção do poema.'),
 vf('Se retirássemos a recordação da abundância passada, a perda presente manteria exatamente o mesmo efeito.',False,'A recordação fornece um termo de comparação. Retirá-la reduziria a possibilidade de perceber a transformação do vínculo, mesmo que a despedida continuasse explícita.'),
 read('Para levar', '<p class="levar">Uma palavra pode manter o significado e perder a força numa relação.</p><p>Explica oralmente uma imagem, o contraste que a modifica e uma conclusão que o poema não autoriza. Na tarefa da unidade, compara os textos sem transformar o autor na voz de todos os versos.</p>', 'Para levar'),
])

lesson('m8-f14', 'A história de uma tigela', 1, 'm8-f05',
       'Quem decide o que merece entrar na história?', [
 read('A história de uma tigela', '<p class="abre">Uma tigela partida pode parecer um acontecimento pequeno. O que acontece quando o poema lhe dá a atenção reservada às grandes descobertas?</p><p>Já leste a abertura. Agora vais seguir a mudança de escala e distinguir um objeto, uma memória e o valor que lhes atribuímos.</p>', 'Abre'),
 read('O essencial', '<p>Ana Luísa Amaral faz da vida quotidiana matéria de reflexão em «A verdade histórica». A voz que escreve também vive as exigências do espaço doméstico. Esse cruzamento não autoriza tratar cada acontecimento do poema como prova biográfica.</p><p>A <strong>ironia</strong> põe em tensão o que parece importante e aquilo que normalmente passa despercebido. A mudança de escala entre uma casa e a história pode tornar visíveis critérios de valor.</p>', 'O essencial'),
 read('Uma ocorrência doméstica', '<blockquote>«A minha filha partiu uma tigela<br>na cozinha.<br>E eu que me apetecia escrever<br>sobre o evento,»</blockquote><p>Ana Luísa Amaral, «A verdade histórica», em <i>PÁ: Poesia &amp; Outras Artes</i>, n.º 0, Casa Comum/U.Porto Press, setembro de 2023, pp. 14–15. Publicação com autorização da Assírio &amp; Alvim, identificada nos créditos.</p><p><a href="'+TIGELA+'" target="_blank" rel="noopener">Lê o poema completo na publicação da U.Porto</a>. Segue a passagem do incidente doméstico à imaginação de um futuro distante.</p>'),
 choice('Que contraste se abre nos quatro versos citados?', ['O incidente doméstico torna-se matéria de escrita.', 'Uma descoberta histórica dispensa a vida doméstica.', 'Uma notícia pública interrompe uma pesquisa antiga.'],0,'O desejo de escrever nasce do incidente. O poema dá atenção a um acontecimento que poderia ser descartado como insignificante.'),
 vf('A presença de uma filha no poema permite identificar o episódio como um acontecimento comprovado da vida da autora.',False,'A relação familiar faz parte da cena enunciada. Para a transformar em informação biográfica é necessária uma fonte diferente do próprio poema.'),
 pairs('Liga cada plano à pergunta que o torna relevante.', [['A tigela partida','Que acontecimento desencadeia a reflexão?'],['A vontade de escrever','Que experiência se transforma em linguagem?'],['A imaginação de um futuro distante','Que valor poderá ser atribuído ao objeto?']], 'Os planos articulam acontecimento, criação e valor. Não são três assuntos independentes: cada um muda a leitura do anterior.'),
 read('Do fragmento ao valor', '<p>No poema completo, a imaginação aproxima a tigela quotidiana de objetos a que o tempo e a história dão prestígio. A origem concreta e o uso banal impedem que essa aproximação se torne uma celebração solene.</p><p>Modelo: identificar uma mudança de escala, explicar o contraste e perguntar quem atribui valor. Não basta concluir que o poema trata de loiça.</p>'),
 fill('Completa a interpretação da mudança de escala.', 'A passagem do doméstico ao histórico altera o [1] atribuído ao objeto, sem transformar a imaginação numa [2] arqueológica.', [(['valor','custo','ritmo'],0),(['prova','rasto','ruína'],0)], 'A imaginação testa critérios de valor. Não documenta uma descoberta real nem muda fisicamente a tigela.'),
 order('Ordena um percurso de interpretação, do acontecimento à pergunta crítica.', ['Localizar o incidente doméstico','Observar a mudança para um futuro imaginado','Comparar os valores atribuídos ao mesmo objeto','Questionar o que costuma merecer memória'], 'A pergunta crítica nasce do contraste construído no poema. Sem esse percurso, seria apenas uma opinião sobre a importância da história.'),
 underline('No exemplo didático criado, seleciona a palavra que apresenta uma possibilidade, não uma certeza.', 'Talvez guardassem aquele fragmento.', [0], 'Talvez marca uma hipótese. O exemplo é criado para treinar a diferença entre imaginar um destino e afirmar um facto.'),
 choice('Que leitura preserva a força crítica da mudança de escala?', ['Interrogar o prestígio dado aos vestígios.', 'Declarar sem valor qualquer objeto de museu.', 'Provar que toda a loiça se torna património.'],0,'A comparação interroga critérios de prestígio. Não obriga a desprezar museus nem a atribuir o mesmo valor a todos os objetos.'),
 vf('Reconhecer ironia dispensa explicar a relação entre os dois planos contrastados.',False,'A etiqueta ironia não demonstra a leitura. É preciso mostrar que expectativas de grandeza são aproximadas do episódio quotidiano e como essa aproximação as altera.'),
 read('O que resiste?', '<p>O desfecho associa a resistência de um material banal ao destino dos fragmentos. Essa inversão permite perguntar se durar muito e merecer memória são a mesma coisa.</p><p>Não substituas esta pergunta por uma conclusão pronta. Regressa ao fim do poema e confronta o valor material, o valor afetivo e o valor histórico.</p>'),
 pairs('Distingue três critérios, sem os confundir.', [['Resistir fisicamente durante muito tempo','Durabilidade material'],['Recordar uma relação ou um momento vivido','Valor afetivo'],['Ajudar a compreender uma sociedade','Valor histórico']], 'Um objeto pode reunir vários valores, mas nenhum deles prova automaticamente os outros. A duração física não mede, por si só, importância humana.'),
 choice('Que proposta de exposição transfere melhor a pergunta do poema?', ['Comparar um objeto banal e um prestigiado, explicando as legendas.', 'Ordenar objetos pelo seu preço, tomando o custo como valor absoluto.', 'Eliminar objetos correntes, reservando a memória aos mais raros.'],0,'A comparação obriga a explicitar critérios. A atividade não decide antecipadamente que um objeto merece mais atenção apenas pelo preço ou pela raridade.'),
 fill('Completa uma conclusão que distingue duas formas de duração.', 'Um material pode durar sem conservar uma [1]; uma experiência breve pode tornar-se [2].', [(['memória','textura','grandeza'],0),(['memorável','duradoura','previsível'],0)], 'A oposição separa persistência física e significado humano. É uma hipótese de leitura, não uma regra que classifica todos os objetos.'),
 order('Organiza a preparação de uma legenda crítica para um objeto teu.', ['Descrever o objeto sem lhe atribuir prestígio','Identificar um uso ou uma relação concreta','Explicar por que merece atenção nesse contexto','Distinguir o que sabes do que imaginas'], 'A legenda parte do observável e torna explícita a atribuição de valor. A imaginação pode entrar, desde que não se apresente como informação comprovada.'),
 choice('Que comparação com outro poema evita uma conclusão apenas temática?', ['Explicar como cada voz transforma um objeto em pergunta.', 'Enumerar os objetos, sem interpretar a presença de cada um.', 'Dizer que ambos falam da vida, sem indicar qualquer contraste.'],0,'Comparar a transformação de um objeto em pergunta relaciona forma e sentido. Um tema muito amplo não explica a singularidade de cada poema.'),
 vf('Uma legenda que atribui valor afetivo a um objeto deve explicar a relação que sustenta esse valor.',True,'A ligação a uma experiência torna compreensível o valor afetivo. Sem a explicitar, a legenda apenas declara importância e não permite perceber o seu critério.'),
 read('Para levar', '<p class="levar">Durar, valer e merecer memória não são a mesma coisa.</p><p>Escolhe um objeto comum e propõe oralmente duas legendas: uma sobre o uso, outra sobre a memória. Explica o que mudaste e distingue informação de imaginação.</p>', 'Para levar'),
])

lesson('m8-f15', 'A autora não é o poema', 1, 'm8-f14',
       'Como usar uma reportagem sobre uma autora sem reduzir o poema à sua vida?', [
 read('A autora não é o poema', '<p class="abre">Saber mais sobre quem escreve pode abrir uma leitura. Também pode fechá-la cedo demais. Que informação ajuda e que conclusão vai além da prova?</p><p>Vais cruzar uma reportagem da RTP Ensina com as distinções que já usaste ao ler Ana Luísa Amaral.</p>', 'Abre'),
 read('O essencial', '<p><strong>Autora:</strong> pessoa real que escreve. <strong>Voz poética:</strong> instância construída no poema. <strong>Reportagem:</strong> seleção jornalística de informações, declarações e imagens.</p><p>Uma reportagem pode documentar uma declaração da autora. Não prova automaticamente que todas as vozes dos seus poemas dizem o que ela pensa em cada momento.</p>', 'O essencial'),
 read('Uma fonte, um âmbito', '<p>A RTP Ensina apresenta Ana Luísa Amaral em «Ana Luísa Amaral, poesia atenta ao mundo». A página associa a sua escrita à atenção ao quotidiano e às desigualdades e apresenta o livro <i>Mundo</i>. O recurso audiovisual tem origem em <i>Nada Será Como Dante</i>, produção Até ao Fim do Mundo, 2021.</p><p><a href="'+REPORTAGEM+'" target="_blank" rel="noopener">Lê a apresentação na RTP Ensina</a>. Procura uma informação sobre o trabalho de escrita e outra sobre o âmbito da reportagem. O texto de apresentação basta para as atividades desta lição.</p><p>Não é uma reportagem sobre a origem de «A verdade histórica». Evita atribuir-lhe essa função.</p>'),
 choice('Que afirmação respeita o âmbito da fonte apresentada?', ['A reportagem contextualiza a atenção da autora ao mundo.', 'A reportagem comprova a origem de cada poema da autora.', 'A reportagem substitui a análise das vozes de todos os poemas.'],0,'A fonte oferece contexto sobre a autora e apresenta uma obra. A ligação a um poema específico exige observar esse poema e não presumir a sua origem.'),
 vf('Uma frase na primeira pessoa, num poema, deve ser atribuída automaticamente à pessoa que o assina.',False,'Autoria e enunciação são planos diferentes. Uma pessoa real pode criar várias vozes, posições e situações que não coincidem com a sua experiência pessoal.'),
 pairs('Associa cada pergunta ao plano de análise adequado.', [['Quem assina o livro?','Autoria'],['Quem fala dentro do poema?','Enunciação poética'],['Que informações a página escolhe destacar?','Construção jornalística']], 'As perguntas não se substituem. Saber quem assina não resolve quem fala nem explica as escolhas da reportagem.'),
 read('Um modelo de confronto', '<p>Exemplo de raciocínio: a reportagem destaca uma atenção à vida quotidiana. Num poema, encontras um objeto doméstico a desencadear uma reflexão. Podes investigar uma aproximação entre essas duas observações.</p><p>Não podes concluir, apenas por isso, que o incidente aconteceu exatamente como é narrado. A aproximação orienta uma pergunta; não fornece uma certidão do acontecimento.</p>'),
 fill('Completa a relação entre contexto e interpretação.', 'A reportagem oferece [1]; o poema fornece os indícios para a [2] do texto.', [(['contexto','confissão','garantias'],0),(['leitura','autoria','revisão'],0)], 'O contexto pode tornar visíveis perguntas relevantes. A interpretação mantém a responsabilidade de demonstrar o que afirma no texto.'),
 order('Ordena uma utilização rigorosa de informação biográfica.', ['Identificar a fonte e o que ela efetivamente afirma','Localizar um indício pertinente no poema','Formular uma aproximação entre os dois','Indicar o limite dessa aproximação'], 'A fonte é lida antes de ser usada. O confronto com o poema e a indicação do limite evitam substituir análise por biografia.'),
 underline('Seleciona a palavra que torna prudente esta hipótese didática criada.', 'Esta informação pode orientar uma leitura.', [2], 'Pode apresenta uma possibilidade, não uma relação obrigatória. A hipótese continua a precisar de confirmação textual.'),
 choice('Que pergunta abre uma investigação, em vez de impor uma resposta?', ['Como se constrói a atenção ao quotidiano neste poema?', 'Que facto da vida da autora explica sempre este poema?', 'Porque representa a primeira pessoa sempre a autora real?'],0,'A primeira pergunta procura procedimentos do texto. As outras já impõem como verdade aquilo que seria necessário demonstrar.'),
 vf('Distinguir autora e voz poética obriga a ignorar toda a informação sobre a autora.',False,'A distinção permite usar melhor a informação. O contexto continua relevante quando não é confundido com prova automática de cada acontecimento ou voz.'),
 read('Reconhecer uma atribuição', '<p>Formulações didáticas criadas: A: «A página apresenta o livro como atento a desigualdades.» B: «A autora afirmou esta frase.» C: «A voz deste poema é necessariamente a autora.»</p><p>A exige conferir a apresentação. B exige localizar a declaração exata. C não decorre nem de A nem de B. Não ponhas entre aspas uma paráfrase tua.</p>'),
 pairs('Liga a formulação ao cuidado necessário.', [['A página destaca um tema.','Conferir a apresentação da fonte'],['A autora disse estas palavras.','Localizar a declaração exata'],['O poema permite esta hipótese.','Apresentar indícios textuais']], 'A atribuição deve acompanhar a natureza da prova. Uma paráfrase de reportagem não se transforma em declaração literal da autora.'),
 choice('Que legenda identifica corretamente uma paráfrase tua?', ['Síntese da apresentação publicada pela RTP Ensina.', 'Palavras exatas da autora, sem confirmação na fonte.', 'Verso do poema, embora retirado de uma reportagem.'],0,'Síntese explicita a transformação realizada. As outras legendas mudam a origem e o estatuto do texto e podem criar uma falsa citação.'),
 fill('Completa uma regra de atribuição.', 'As aspas assinalam uma [1] literal; a paráfrase conserva a indicação de [2].', [(['citação','hipótese','opinião'],0),(['origem','métrica','género'],0)], 'Uma paráfrase também precisa de atribuição. As aspas não servem para dar autoridade a palavras que a fonte não contém.'),
 order('Prepara uma apresentação oral curta sobre autora e poema.', ['Apresentar um dado pertinente com a fonte','Indicar a pergunta que esse dado sugere','Analisar um indício do poema','Explicar o que continua sem prova'], 'A apresentação faz o contexto trabalhar para a leitura. O limite final não enfraquece a análise: torna o seu alcance verificável.'),
 choice('Que proposta criativa testa melhor a distinção estudada?', ['Criar duas vozes diferentes para observar o mesmo objeto.', 'Copiar uma informação biográfica e chamar-lhe voz poética.', 'Atribuir à autora uma frase inventada para completar a notícia.'],0,'Duas vozes para o mesmo objeto permitem experimentar que quem escreve e quem fala não são necessariamente a mesma instância. As frases criadas devem ser identificadas como tal.'),
 vf('Duas interpretações podem usar o mesmo dado biográfico e continuar a precisar de provas diferentes no poema.',True,'O contexto não determina uma única leitura. Cada interpretação tem de demonstrar as relações textuais que propõe, mesmo quando parte da mesma informação.'),
 read('Para levar', '<p class="levar">O contexto abre perguntas; o texto sustenta respostas.</p><p>Formula oralmente uma aproximação entre a reportagem e um poema lido. Inclui um dado, um indício e um limite. Não atribuas à reportagem uma explicação da origem de «A verdade histórica».</p>', 'Para levar'),
])

